def mad(xs):
    if not xs:
        return 0

    def median(vals):
        s = sorted(vals)
        n = len(s)
        mid = n // 2
        if n % 2:
            return s[mid]
        return (s[mid - 1] + s[mid]) / 2

    med = median(xs)
    return median([abs(x - med) for x in xs])
