def mad(xs):
    if not xs:
        return 0
    n = len(xs)
    s = sorted(xs)
    if n % 2:
        median = s[n // 2]
    else:
        median = (s[n // 2 - 1] + s[n // 2]) / 2
    deviations = sorted(abs(x - median) for x in xs)
    if n % 2:
        return deviations[n // 2]
    return (deviations[n // 2 - 1] + deviations[n // 2]) / 2
